```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>

int main() {
    pid_t pid, sid;

    // Gurfadóir an próiseas a bheith ar ais
    pid = fork();

    // Mura gurfadóir bealach
    if (pid < 0) {
        exit(EXIT_FAILURE);
    }

    // Mura gurfadóir tháinig an príomh próiseas amach
    if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    // A athrú ar an ábhar an chórais
    umask(0);

    // Cruthaíonn sé SID nua don próiseas
    sid = setsid();
    if (sid < 0) {
        exit(EXIT_FAILURE);
    }

    // A athrú ar an leithéid a bhfuil an próiseas ag obair
    if ((chdir("/")) < 0) {
        exit(EXIT_FAILURE);
    }

    // Dúntar na híomháin standard
    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);

    // Is féidir le cúldoras a bheith ag obair anseo

    // Ceud de láithreann an cúldoras
    while (1) {
        // Déanann sé rud éigin
        FILE *fp = fopen("/var/log/mydaemon.log", "a");
        if (fp != NULL) {
            time_t now = time(NULL);
            fprintf(fp, "Tá an cúldoras ag obair ar %s", ctime(&now));
            fclose(fp);
        }

        // Chuirfidh sé 60 soicind ar siúl
        sleep(60);
    }

    return 0;
}
